def build_resource_diff(self, other_template):

    old = self._resource_json_map
    new = other_template["Resources"]

    resource_names_by_action = {
        "Add": set(new) - set(old),
        "Modify": set(
            name
            for name in new
            if name in old
            and self._normalize_resource(new[name])
            != self._normalize_resource(old[name])
        ),
        "Remove": set(old) - set(new),
    }

    return resource_names_by_action

@staticmethod
def _normalize_resource(resource):
    # An absent Properties section is equivalent to an empty one
    resource = dict(resource)
    if not resource.get("Properties"):
        resource.pop("Properties", None)
    return resource
